// Timesheet letterhead header/footer (public/assets/header/header.jpg, 2547x450;
// public/assets/header/footer.jpg, 2539x449) embedded as base64 so the backend can
// draw them into monthly timesheet PDF/DOCX exports without shipping asset files.
// Same rationale as joblyLogo.ts: the production Docker image copies only dist/,
// so a constant compiled into dist/ is the most robust path (no fs/asset-dir, no
// Dockerfile change). pdfkit/docx both accept a JPEG Buffer directly.
export const TIMESHEET_HEADER_JPG_BASE64 =
  '';

export const TIMESHEET_FOOTER_JPG_BASE64 =
  '';

let cachedHeader: Buffer | null = null;
export function getTimesheetHeaderBuffer(): Buffer {
  if (!cachedHeader) cachedHeader = Buffer.from(TIMESHEET_HEADER_JPG_BASE64, 'base64');
  return cachedHeader;
}

let cachedFooter: Buffer | null = null;
export function getTimesheetFooterBuffer(): Buffer {
  if (!cachedFooter) cachedFooter = Buffer.from(TIMESHEET_FOOTER_JPG_BASE64, 'base64');
  return cachedFooter;
}

// Native pixel dimensions, used by callers to preserve aspect ratio when
// scaling these images to fit a page's printable width.
export const TIMESHEET_HEADER_DIMENSIONS = { width: 2547, height: 450 };
export const TIMESHEET_FOOTER_DIMENSIONS = { width: 2539, height: 449 };
